<?php
namespace Tests\Feature;use App\Models\{ContactItem,Setting,Social,User};use Database\Seeders\DatabaseSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class GlobalContentAdminCrudTest extends TestCase{use RefreshDatabase;private function login():void{$this->seed(DatabaseSeeder::class);$this->actingAs(User::where('email','superadmin@admin.com')->firstOrFail());}
 public function test_contact_item_english_crud_and_filters():void{$this->login();$this->post(route('contact_items.store'),['icon'=>'phone','link'=>'tel:123','order'=>5,'is_active'=>1,'en'=>['title'=>'Reservations','value'=>'123']])->assertRedirect();$item=ContactItem::whereTranslation('title','Reservations')->firstOrFail();$this->get(route('contact_items.index',['q'=>'Reservations','status'=>'1']))->assertOk()->assertSee('Reservations');$this->put(route('contact_items.update',$item),['icon'=>'mail','link'=>'mailto:test@example.com','order'=>2,'en'=>['title'=>'Email us','value'=>'test@example.com']])->assertRedirect();$this->assertDatabaseHas('contact_item_translations',['contact_item_id'=>$item->id,'title'=>'Email us']);$this->delete(route('contact_items.destroy',$item))->assertRedirect();$this->assertSoftDeleted($item);}
 public function test_social_crud_uses_icon_field_and_filters():void{$this->login();$this->post(route('socials.store'),['title'=>'TikTok','icon'=>'tiktok','link'=>'https://tiktok.com/test','is_active'=>1,'order'=>5])->assertRedirect();$social=Social::where('title','TikTok')->firstOrFail();$this->get(route('socials.index',['q'=>'TikTok','status'=>'1']))->assertOk()->assertSee('tiktok');$this->put(route('socials.update',$social),['title'=>'TikTok Updated','icon'=>'brand-tiktok','link'=>'https://tiktok.com/updated','order'=>1])->assertRedirect();$this->assertDatabaseHas('socials',['id'=>$social->id,'icon'=>'brand-tiktok']);$this->delete(route('socials.destroy',$social))->assertRedirect();$this->assertSoftDeleted($social);}
 public function test_settings_are_filterable_editable_and_permission_protected():void{$this->login();$this->get(route('settings.index',['q'=>'site_name']))->assertOk()->assertSee('site_name');$this->put(route('settings.update'),['settings'=>['site_name'=>'DreamTour Canada','phone'=>'555-1234']])->assertRedirect();$this->assertSame('DreamTour Canada',Setting::get('site_name'));$this->assertSame('555-1234',Setting::get('phone'));$other=User::factory()->create();$this->actingAs($other)->get(route('settings.index'))->assertForbidden();}
}
